public static class Validation {
 // Loot can be any native item, or a desktop file a corpse can hold: bags/backpacks, research papers/maps
 // and notes. Bases, stores and the player/world/music/quest system files are not droppable.
 static readonly string[] LootFileTypes={"file","image","text"};
 public static bool Droppable(ReferenceObject o){if(o==null)return false;if(o.Kind=="item")return o.Object!="obj_ItemBase";string type=o.Fields.TryGetValue("fileType",out var f)?(f.Value is JsonElement j?j.ToString():f.Value?.ToString())??"":"";return LootFileTypes.Contains(type)&&o.Object!="obj_File"&&o.Object!="obj_ImageBase"&&o.Object!="obj_BaseStore"&&o.Parent!="obj_BaseStore";}
 public static bool Identifier(string s)=>s!=null&&Regex.IsMatch(s,@"^[a-z][a-z0-9_]{0,47}$");
 public static string Within(string root,string relative,bool exists=true){
  if(string.IsNullOrWhiteSpace(relative)||Path.IsPathRooted(relative)||relative.Contains(':'))throw new Exception("Path must be relative: "+relative);
  string full=Path.GetFullPath(Path.Combine(root,relative));string prefix=Path.GetFullPath(root).TrimEnd(Path.DirectorySeparatorChar)+Path.DirectorySeparatorChar;
  if(!full.StartsWith(prefix,StringComparison.OrdinalIgnoreCase))throw new Exception("Path escapes project: "+relative);
  for(var p=full;p!=null&&p.StartsWith(prefix,StringComparison.OrdinalIgnoreCase);p=Path.GetDirectoryName(p))if((File.Exists(p)||Directory.Exists(p))&&(File.GetAttributes(p)&FileAttributes.ReparsePoint)!=0)throw new Exception("Linked paths are not permitted: "+relative);
  if(exists&&!File.Exists(full))throw new Exception("Missing project file: "+relative);return full;
 }
 public static List<ValidationError> Check(List<Manifest> mods,Catalog cat){var errors=RevisionValidation.Check(mods,cat);mods=mods.Select(Revision.Runtime).ToList();var ids=new HashSet<string>(StringComparer.OrdinalIgnoreCase);var slots=new HashSet<string>();var patches=new HashSet<string>();var resources=new HashSet<string>();
  foreach(var m in mods){string current="";void Err(string f,object val,string msg)=>errors.Add(new(){Mod=m.Id,Enemy=current,Field=f,Value=val??"null",Message=msg});
   void Num(string f,double v,double min=0,double max=100000){string key=System.Text.RegularExpressions.Regex.Replace(f,@"^(actions|whenAttacked|periodic|whenGone).*\.([A-Za-z]+)$","action.$2");if(Limits.Rules.TryGetValue(key,out var rule)){min=Math.Max(min,rule.Min);max=Math.Min(max,rule.Max);}if(!double.IsFinite(v)||v<min||v>max)Err(f,v,$"Expected {min} through {max}");}
   void FileRef(string f,string p){try{Within(m.Directory,p);}catch(Exception e){Err(f,p,e.Message);}}
   if(m.SchemaVersion!=3)Err("schemaVersion",m.SchemaVersion,"Only schema version 3 is supported");if(!Identifier(m.Id)||!ids.Add(m.Id))Err("id",m.Id,"Invalid or duplicate mod ID");if(m.Name.Length>200||m.Version.Length>80)Err("name/version",m.Name,"Text too long");
   var enemies=new HashSet<string>();foreach(var e in m.Enemies){if(!Identifier(e.Id)||!enemies.Add(e.Id))Err("id",e.Id,"Invalid or duplicate enemy ID");if(!resources.Add(Compiler.Obj(m,e.Id)))Err("id",e.Id,"Generated asset name conflicts with another mod");}if(m.Enemies.Count>128)Err("enemies",m.Enemies.Count,"Expected 0–128 enemies");
   foreach(var a in m.Assets){if(!Identifier(a.Key)||!resources.Add("spr_v2_"+m.Id+"_"+a.Key))Err("assets",a.Key,"Invalid or conflicting asset");FileRef("assets."+a.Key,a.Value);if(Path.GetExtension(a.Value).ToLowerInvariant()!=".png")Err("assets."+a.Key,a.Value,"Only PNG images are supported");else try{var b=File.ReadAllBytes(Within(m.Directory,a.Value));AssetValidation.Png(b);}catch(Exception ex){Err("assets."+a.Key,a.Value,ex.Message);}}
   foreach(var audio in m.Audio){if(!Identifier(audio.Key))Err("audio",audio.Key,"Invalid audio name");try{AudioAssets.Check(Within(m.Directory,audio.Value.File),audio.Value.Kind);if(audio.Value.Original!="")Within(m.Directory,audio.Value.Original);}catch(Exception ex){Err("audio."+audio.Key,audio.Value.File,ex.Message);}}
