   bool Image(string s)=>m.Assets.ContainsKey(s)||cat.Sprites.Contains(s);var variants=new HashSet<string>();foreach(var v in m.StatusVariants){if(!Identifier(v.Id)||!variants.Add(v.Id))Err("statusVariants.id",v.Id,"Invalid or duplicate variant");if(!cat.NativeStatusFamilies.Contains(v.Family))Err("statusVariants.family",v.Family,"Unknown native family");if(v.Icon!=""&&!Image(v.Icon))Err("statusVariants.icon",v.Icon,"Unknown image");}
   foreach(var e in m.Enemies){current=e.Id;SoundRef("spawnSound",e.SpawnSound,"sound");SoundRef("music",e.Music,"music");if(!new[]{"enemy","hazard","cosmetic"}.Contains(e.Mode))Err("mode",e.Mode,"Choose enemy or hazard");Num("activationSeconds",e.ActivationSeconds,.01,3600);if(!Image(e.Image))Err("image",e.Image,"Unknown symbolic image");if(!new[]{"Undead","Beast","Human","Demon","Alien",""}.Contains(e.Type))Err("type",e.Type,"Unknown native type");if(!new[]{"Minion","Elite","Boss"}.Contains(e.Rank))Err("rank",e.Rank,"Unknown rank");if(e.Name.Length>160||e.Description.Length>8000)Err("name/description",e.Name,"Text too long");
    foreach(var p in typeof(Stats).GetProperties())Num("stats."+p.Name,(double)p.GetValue(e.Stats));Num("stats.maxHealth",e.Stats.MaxHealth,1);if(e.Stats.MaxDamage<e.Stats.MinDamage)Err("stats.maxDamage",e.Stats.MaxDamage,"Must be at least minDamage");if(e.Stats.GoldMax<e.Stats.GoldMin)Err("stats.goldMax",e.Stats.GoldMax,"Must be at least goldMin");foreach(var p in typeof(Resistance).GetProperties())Num("advanced."+p.Name,(double)p.GetValue(e.Advanced),.001);
    var pools=new HashSet<string>();foreach(var p in e.Encounters){if(!cat.Pools.Any(x=>x.Name==p.Pool)||!pools.Add(p.Pool))Err("encounters.pool",p.Pool,"Unknown or duplicate pool");Num("encounters.weight",p.Weight,0,1000000);}
    Num("treasureRolls",e.TreasureRolls,0,10);Num("treasureChance",e.TreasureChance,0,100);
    foreach(var l in e.Loot){if(l.Name.Length>160)Err("loot.name",l.Name,"Use at most 160 characters");var lootObject=cat.Objects.FirstOrDefault(x=>x.Object==l.Item);if(!Droppable(lootObject))Err("loot.item",l.Item,"Unknown item object");else if(lootObject.Kind!="item"&&(l.DamageOverride||l.LevelOverride))Err("loot.item",l.Item,"Damage and requirement overrides apply only to items, not bags, papers or notes");Num("loot.chance",l.Chance,0,100);Num("loot.min",l.Min,1,100);Num("loot.max",l.Max,l.Min,100);Num("loot.minLevel",l.MinLevel,1,999);Num("loot.maxLevel",l.MaxLevel,l.MinLevel,999);if(l.DamageOverride){Num("loot.damageMin",l.DamageMin,0,100000);Num("loot.damageMax",l.DamageMax,l.DamageMin,100000);}if(l.LevelOverride){Num("loot.requiredLevelMin",l.RequiredLevelMin,0,999);Num("loot.requiredStrength",l.RequiredStrength,0,999);Num("loot.requiredAgility",l.RequiredAgility,0,999);Num("loot.requiredIntelligence",l.RequiredIntelligence,0,999);Num("loot.requiredLevelMax",l.RequiredLevelMax,l.RequiredLevelMin,999);}Num("loot.weight",l.Weight,.000001,1000000);if(l.Mandatory&&l.Chance!=100)Err("loot.chance",l.Chance,"Mandatory drops must be guaranteed");}
    foreach(var l in e.Loot){var item=cat.Objects.FirstOrDefault(x=>x.Object==l.Item);if(!new[]{"native","random","selected"}.Contains(l.Enchantment))Err("loot.enchantment",l.Enchantment,"Choose native, random, or selected");if(l.Cursed&&!Enchantments.Supported(item))Err("loot.cursed",l.Item,"Only native equippable items can be cursed");if(l.Cursed&&l.Enchantment!="selected"&&item!=null&&Enchantments.Value(item,"unique")=="1")Err("loot.cursed",l.Item,"Unique equipment cannot take a random curse; use 100% selected enchantments with negative amounts instead");if(l.Enchantment!="native"&&!Enchantments.Supported(item))Err("loot.enchantment",l.Item,"Only native equippable items support enchantments; consumables and quest items retain their native behavior");if(l.Enchantment=="random"&&item!=null&&Enchantments.Value(item,"unique")=="1")Err("loot.enchantment",l.Item,"Unique equipment has fixed properties; select additional bonuses instead of rerolling it");if(l.Enchantments==null){Err("loot.enchantments",null,"Expected a list of bonuses");continue;}if(l.Enchantment=="selected"&&(l.Enchantments.Count<1||l.Enchantments.Count>9))Err("loot.enchantments",l.Enchantments.Count,"Select 1–9 guaranteed bonuses");if(l.Enchantment!="selected"&&l.Enchantments.Count>0)Err("loot.enchantments",l.Enchantment,"Bonus selections require selected enchantment mode");var stats=new HashSet<string>();foreach(var b in l.Enchantments){var choice=Enchantments.Choices.FirstOrDefault(x=>x.Id==b.Stat);if(choice==null||!stats.Add(b.Stat))Err("loot.enchantments.stat",b.Stat,"Unknown or duplicate enchantment");if(l.Cursed){Num("loot.enchantments.amount",b.Amount,-(choice?.Max??1000),choice?.Max??1000);if(b.Amount==0)Err("loot.enchantments.amount",b.Amount,"Use a nonzero amount; cursed items allow negative amounts");}else Num("loot.enchantments.amount",b.Amount,1,choice?.Max??1000);}if(item!=null&&Enchantments.Existing(item).Union(stats).Count()>9)Err("loot.enchantments",l.Item,"Selected bonuses and this item's built-in properties exceed nine native bonus slots");}
    foreach(var gr in e.Loot.Where(x=>x.Group!="").GroupBy(x=>x.Group))if(gr.Select(x=>x.Chance).Distinct().Count()!=1||gr.Any(x=>x.Mandatory))Err("loot.group",gr.Key,"Group members share one chance and cannot be mandatory");
    var movement=e.Movement;if(!new[]{"path","line","arc"}.Contains(movement.Shape))Err("movement.shape",movement.Shape,"Choose path, line, or arc");if(!new[]{"center","firstPoint","fixed","randomX","randomY","randomXY"}.Contains(movement.StartMode))Err("movement.startMode",movement.StartMode,"Unknown starting position");Num("movement.bend",movement.Bend,-2,2);Num("movement.gameSpeed",movement.GameSpeed,.01,100);if(movement.Shape!="path"&&movement.Points.Count!=2)Err("movement.points",movement.Points.Count,"Line and arc require two points");Num("movement.intensity",movement.Intensity,0,1000);if(movement.Profile!=""&&!cat.Paths.Any(x=>x.Name==movement.Profile))Err("movement.profile",movement.Profile,"Unknown path");if(movement.Profile!=""&&movement.Points.Count>0)Err("movement",movement.Profile,"Select either native path or custom points");if(!new[]{"linear","ease","catmullRom","bezier"}.Contains(movement.Interpolation))Err("movement.interpolation",movement.Interpolation,"Unknown interpolation");if(!new[]{"none","clamp","wrap","reverse","restart"}.Contains(movement.Boundary))Err("movement.boundary",movement.Boundary,"Unknown boundary policy");if(movement.Points.Count>0&&(movement.Points.Count<1||movement.Points.Count>64||movement.LoopStart<1||movement.LoopStart>movement.Points.Count))Err("movement.loopStart",movement.LoopStart,"Requires 2–64 points and a valid one-based loop start");foreach(var p in movement.Points){Num("movement.x",p.X,-1,2);Num("movement.y",p.Y,-1,2);Num("movement.duration",p.Duration,.01,3600);Num("movement.speed",p.Speed,0,10);Num("movement.wait",p.Wait,0,3600);Num("movement.variance",p.Variance,0,1);Num("movement.controlX",p.ControlX,-2,3);Num("movement.controlY",p.ControlY,-2,3);}
    var cslots=new HashSet<string>();foreach(var c in e.Components){if(!Identifier(c.Slot)||!cslots.Add(c.Slot))Err("components.slot",c.Slot,"Invalid or duplicate slot");if(!enemies.Contains(c.Enemy))Err("components.enemy",c.Enemy,"Unknown enemy in this mod");if(!new[]{"limb","separate"}.Contains(c.Role))Err("components.role",c.Role,"Components are limbs or separate actors; the root is the only head");if(c.DeathAction.Kind!="damageHead")Err("components.deathAction",c.DeathAction.Kind,"Unknown structural action");Num("components.deathAction.amount",c.DeathAction.Amount,0,c.DeathAction.Percent?100:100000);}
    int count=0;void Actions(List<ActionNode> list,string field,int depth,bool periodic){if(depth>12){Err(field,depth,"Action graph too deep");return;}for(int ai=0;ai<list.Count;ai++){var a=list[ai];count++;string f=field+"["+ai+"]";if(count>256){Err(f,count,"Maximum 256 action nodes per enemy");return;}if(!new[]{"trueDamage","magicDamage","resourceChange","presentation","actionMove","wait","damage","sound","strike","lifesteal","manaDrain","heal","mana","status","effect","message","log","window","spawn","projectile","hazard","condition","chance","cooldown","alternate","attackSpeed","variableAction","variableBranch","deleteSelf","returnToPoint"}.Contains(a.Kind))Err(f+".kind",a.Kind,"Unknown action");foreach(var prop in typeof(ActionNode).GetProperties()){var key="action."+char.ToLowerInvariant(prop.Name[0])+prop.Name[1..];if(Limits.Rules.ContainsKey(key)&&prop.GetValue(a) is object raw){var msg=Limits.Check(key,Convert.ToDouble(raw));if(msg!="")Err(f+"."+char.ToLowerInvariant(prop.Name[0])+prop.Name[1..],raw,msg);}}if(a.WaitMin>a.WaitMax)Err(f+".waitMax",a.WaitMax,"Maximum must be at least minimum");if(a.Kind=="status"&&!new[]{"add","reduce","clear"}.Contains(a.StatusOperation))Err(f+".statusOperation",a.StatusOperation,"Choose add, reduce, or clear");if(!new[]{"fixed","randomX","randomY","randomXY"}.Contains(a.Placement))Err(f+".placement",a.Placement,"Unknown placement");if(!new[]{"fixed","randomX","randomY","randomXY"}.Contains(a.WindowPlacement))Err(f+".windowPlacement",a.WindowPlacement,"Unknown window placement");if(!new[]{"absolute","relative"}.Contains(a.WindowBasis))Err(f+".windowBasis",a.WindowBasis,"Choose absolute or relative");if(!new[]{"linear","ease"}.Contains(a.WindowEasing))Err(f+".windowEasing",a.WindowEasing,"Choose linear or ease");if(!new[]{"inherit","clamp","wrap","reverse","none"}.Contains(a.WindowBoundary))Err(f+".windowBoundary",a.WindowBoundary,"Unknown movement boundary");if(a.WindowMinX>a.WindowMaxX)Err(f+".windowMaxX",a.WindowMaxX,"Maximum must be at least minimum");if(a.WindowMinY>a.WindowMaxY)Err(f+".windowMaxY",a.WindowMaxY,"Maximum must be at least minimum");if(!new[]{"set","add","multiply","restoreBase"}.Contains(a.AttackSpeedOperation))Err(f+".attackSpeedOperation",a.AttackSpeedOperation,"Unknown attack-speed operation");if(a.Kind=="deleteSelf"&&e.Mode=="enemy")Err(f+".mode","delete","Delete removes only Cosmetic and hazard windows; defeat combat enemies with damage so death, rewards and kill credit still happen");if(a.Kind=="attackSpeed"){if(e.Mode!="enemy"||a.Target!="attacker")Err(f+".target",a.Target,"Attack speed requires the acting combat enemy (attacker)");if((a.AttackSpeedOperation=="set"||a.AttackSpeedOperation=="multiply")&&a.AttackSpeedValue<0)Err(f+".attackSpeedValue",a.AttackSpeedValue,"Set and multiply require a nonnegative value");}Num(f+".chance",a.Chance,0,100);Num(f+".amount",a.Amount);Num(f+".multiplier",a.Multiplier,0,100);Num(f+".healPerMana",a.HealPerMana,0,100);Num(f+".cooldown",a.Cooldown,.25,3600);if(a.MinDamage.HasValue)Num(f+".minDamage",a.MinDamage.Value);if(a.MaxDamage.HasValue)Num(f+".maxDamage",a.MaxDamage.Value,a.MinDamage??0);if(a.Kind=="strike"&&(a.MinDamage??e.Stats.MinDamage)>(a.MaxDamage??e.Stats.MaxDamage))Err(f+".maxDamage",a.MaxDamage,"Effective maximum must be at least the effective minimum");if(!new[]{"victim","attacker"}.Contains(a.Target))Err(f+".target",a.Target,"Choose victim or attacker");if(a.Kind=="sound")SoundRef(f+".asset",a.Asset,"sound");if(a.Kind=="status"){if(!cat.NativeStatusFamilies.Contains(a.Family))Err(f+".family",a.Family,"Unknown native family");if(a.Family=="curse"&&a.Target=="attacker")Err(f+".target",a.Target,"Native curses apply to the player only");if(a.Variant!=""&&!m.StatusVariants.Any(v=>v.Id==a.Variant&&v.Family==a.Family))Err(f+".variant",a.Variant,"Unknown variant or family mismatch");}if(a.Kind=="effect"){if(!Identifier(a.Group))Err(f+".group",a.Group,"Invalid exclusive group ID");if(a.Icon!=""&&!Image(a.Icon))Err(f+".icon",a.Icon,"Unknown icon");}if(a.Kind=="spawn"){if(!enemies.Contains(a.Enemy))Err(f+".enemy",a.Enemy,"Unknown enemy");if(a.Role!="summon")Err(f+".role",a.Role,"Dynamic spawns must be summons");}if(a.Kind=="projectile"||a.Kind=="hazard"){if(!Compiler.SafeHazards.Contains(a.Asset))Err(f+".asset",a.Asset,"No reviewed spawn adapter for this asset");}if(a.Kind=="condition"&&!new[]{"positiveDamage","blocked","healthBelow","manaBelow","alive","killedByPlayer","killedBySelf","chance"}.Contains(a.Condition))Err(f+".condition",a.Condition,"Unknown condition");if(a.Kind=="window"&&!new[]{"shake","minimize","maximize","restore","move","clearMoveOffset"}.Contains(a.Operation))Err(f+".operation",a.Operation,"Unknown window operation");Actions(a.Children,f+".children",depth+1,periodic);Actions(a.Else,f+".else",depth+1,periodic);for(int pi=0;pi<a.MorePaths.Count;pi++)Actions(a.MorePaths[pi].Children,f+".morePaths["+pi+"].children",depth+1,periodic);if(a.Kind=="alternate"&&(a.PathCount<2||a.PathCount>16))Err(f+".pathCount",a.PathCount,"Alternating uses 2 through 16 paths");}}
    long Expanded(List<ActionNode> nodes,int depth=0){if(depth>12)return 4097;long total=0;foreach(var a in nodes){total+=Math.Max(1,a.Repeat)*(1+Expanded(a.Children,depth+1)+Expanded(a.Else,depth+1)+a.MorePaths.Sum(p=>Expanded(p.Children,depth+1)));if(total>4096)return 4097;}return total;}if(Expanded(e.Actions)>4096||Expanded(e.WhenAttacked)>4096||Expanded(e.Periodic)>4096||e.WhenGone.Any(t=>Expanded(t.Children)>4096))Err("actions.repeat",4097,"Nested repeats may expand to at most 4096 action steps");
    Actions(e.Actions,"actions",0,false);Actions(e.WhenAttacked,"whenAttacked",0,false);Actions(e.Periodic,"periodic",0,true);for(int gi=0;gi<e.WhenGone.Count;gi++){var gt=e.WhenGone[gi];if(gt.Entity!=""&&!enemies.Contains(gt.Entity)&&!Compiler.SafeHazards.Contains(gt.Entity))Err("whenGone["+gi+"].entity",gt.Entity,"Choose an entity from this project or a native projectile");Actions(gt.Children,"whenGone["+gi+"].children",1,false);}if(e.AdvancedGml!="")FileRef("advancedGml",e.AdvancedGml);
