   // Static component trees cannot cycle. Recursive dynamic summons are intentionally allowed.
   bool Cycle(string id,HashSet<string> path){if(!path.Add(id))return true;var e=m.Enemies.FirstOrDefault(x=>x.Id==id);if(e!=null)foreach(var c in e.Components)if(Cycle(c.Enemy,new(path)))return true;return false;}
   foreach(var e in m.Enemies)if(Cycle(e.Id,new())){current=e.Id;Err("components",e.Id,"Static component cycle; use capped summon actions for recursion");}
   current="";foreach(var o in m.Overrides){var a=cat.Adapters.FirstOrDefault(x=>x.Slot==o.Slot);if(!slots.Add(o.Slot))Err("overrides.slot",o.Slot,"Conflict: multiple mods override the same slot");if(a==null||a.Classification=="unsafe")Err("overrides.slot",o.Slot,"No reviewed supported adapter for this slot");if(!enemies.Contains(o.Enemy))Err("overrides.enemy",o.Enemy,"Unknown enemy");if(o.Slot=="obj_DemonBossSpawner"&&o.Components.GetValueOrDefault("Head")!=o.Enemy)Err("overrides.components.Head",o.Components.GetValueOrDefault("Head"),"Head mapping must equal the selected override enemy");if(a!=null&&!a.RequiredComponents.Order().SequenceEqual(o.Components.Keys.Order()))Err("overrides.components",o.Components.Keys.ToArray(),"Exact required mappings: "+string.Join(", ",a.RequiredComponents));foreach(var c in o.Components)if(!enemies.Contains(c.Value))Err("overrides.components."+c.Key,c.Value,"Unknown enemy");}
